use gta_browser_launcher::{config::Settings, server, tls};

// The fixture must be generated by LauncherApp/lan_tls.py, not by the Rust implementation under test.
#[tokio::test]
#[ignore = "Requires GTA_LEGACY_CA_FIXTURE generated by the Python launcher"]
async fn python_rsa_ca_is_reused_without_replacing_client_trust() {
    let source = std::path::PathBuf::from(
        std::env::var("GTA_LEGACY_CA_FIXTURE").expect("Python fixture path"),
    );
    let temp = tempfile::tempdir().unwrap();
    let folder = temp.path();
    std::fs::create_dir_all(folder.join("lan-tls")).unwrap();
    std::fs::create_dir_all(folder.join("mirror/playgta5.com")).unwrap();
    std::fs::write(
        folder.join("mirror/playgta5.com/launcher.html"),
        "legacy CA test",
    )
    .unwrap();
    for name in ["lan-root-ca.pem", "lan-root-ca.key", "lan-root-ca.cer"] {
        std::fs::copy(
            source.join("lan-tls").join(name),
            folder.join("lan-tls").join(name),
        )
        .unwrap();
    }
    let original = std::fs::read(folder.join("lan-tls/lan-root-ca.cer")).unwrap();
    let key = std::fs::read(folder.join("lan-tls/lan-root-ca.key")).unwrap();
    assert!(String::from_utf8_lossy(&key).contains("BEGIN RSA PRIVATE KEY"));
    let (cert, key_path) = tls::generate(folder).unwrap();
    assert_eq!(
        original,
        std::fs::read(folder.join("lan-tls/lan-root-ca.cer")).unwrap()
    );
    assert_eq!(
        key,
        std::fs::read(folder.join("lan-tls/lan-root-ca.key")).unwrap()
    );
    let port = std::net::TcpListener::bind("127.0.0.1:0")
        .unwrap()
        .local_addr()
        .unwrap()
        .port();
    let settings = Settings {
        port,
        mode: "lan".into(),
        https: true,
        tls_cert: cert,
        tls_key: key_path,
        ..Default::default()
    };
    let host = server::start_with_options(
        folder,
        settings,
        "",
        server::StartOptions {
            loopback_only: true,
            advertise: false,
        },
    )
    .await
    .unwrap();
    let client = reqwest::Client::builder()
        .no_proxy()
        .add_root_certificate(reqwest::Certificate::from_der(&original).unwrap())
        .timeout(std::time::Duration::from_secs(5))
        .build()
        .unwrap();
    let body = client
        .get(format!("https://localhost:{port}/launcher.html"))
        .send()
        .await
        .unwrap()
        .text()
        .await
        .unwrap();
    assert_eq!(body, "legacy CA test");
    host.stop().await;
}
